package fr.bbodin.courbedepoids;
import android.content.Context;import android.content.SharedPreferences;import org.json.JSONArray;import org.json.JSONException;import org.json.JSONObject;import java.util.ArrayList;import java.util.List;
public final class BackupManager{
 public static final int FORMAT_VERSION=2;private static final String PREFS="settings";private BackupManager(){}
 public static JSONObject createBackup(Context context,WeightDatabase database)throws JSONException{JSONObject root=new JSONObject();root.put("format","courbe-de-poids-backup");root.put("formatVersion",FORMAT_VERSION);root.put("createdAt",System.currentTimeMillis());JSONArray events=new JSONArray();for(WeightDatabase.GenericEvent e:database.allGenericEvents()){JSONObject item=new JSONObject();item.put("typeId",e.typeId);item.put("date",e.date);item.put("createdAt",e.createdAt);item.put("payload",e.payload);events.put(item);}root.put("genericEvents",events);SharedPreferences p=context.getSharedPreferences(PREFS,Context.MODE_PRIVATE);JSONObject settings=new JSONObject();settings.put("reminderEnabled",p.getBoolean("reminder_enabled",false));settings.put("reminderHour",p.getInt("reminder_hour",8));settings.put("reminderMinute",p.getInt("reminder_minute",0));root.put("settings",settings);return root;}
 public static int restoreBackup(Context context,WeightDatabase database,JSONObject root)throws JSONException{if(!"courbe-de-poids-backup".equals(root.optString("format"))||root.optInt("formatVersion",-1)!=FORMAT_VERSION)throw new JSONException("Format de sauvegarde non pris en charge");JSONArray array=root.optJSONArray("genericEvents");JSONObject settings=root.optJSONObject("settings");if(array==null||settings==null)throw new JSONException("Sauvegarde incomplète");List<WeightDatabase.GenericEvent> events=new ArrayList<>();for(int i=0;i<array.length();i++){JSONObject item=array.optJSONObject(i);if(item==null)throw new JSONException("Événement générique invalide");String type=item.optString("typeId",""),date=item.optString("date","");long created=item.optLong("createdAt",-1);String payload=item.optString("payload","");if(!WeightDatabase.isValidGenericEvent(type,date,created,payload))throw new JSONException("Événement générique invalide");events.add(new WeightDatabase.GenericEvent(0,type,date,created,payload));}int hour=settings.optInt("reminderHour",8),minute=settings.optInt("reminderMinute",0);if(hour<0||hour>23||minute<0||minute>59)throw new JSONException("Configuration du rappel invalide");database.replaceGenericEvents(events);boolean enabled=settings.optBoolean("reminderEnabled",false);context.getSharedPreferences(PREFS,Context.MODE_PRIVATE).edit().putBoolean("reminder_enabled",enabled).putInt("reminder_hour",hour).putInt("reminder_minute",minute).apply();if(enabled)ReminderScheduler.schedule(context,hour,minute);else ReminderScheduler.cancel(context);AutoBackupScheduler.backupIfEnabled(context);return events.size();}
}
